contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount) public {
        require(true);

        uint256 supplyBefore = c.totalSupply();
        uint256 distBefore = c.totalDistributed();
        uint256 ownerBalBefore = c.balanceOf(address(this));

        require(amount <= ownerBalBefore);

        c.burn(amount);

        uint256 supplyAfter = c.totalSupply();
        uint256 distAfter = c.totalDistributed();
        uint256 ownerBalAfter = c.balanceOf(address(this));

        assert(
            supplyBefore >= amount &&
            distBefore >= amount &&
            supplyAfter == supplyBefore - amount &&
            distAfter == distBefore - amount &&
            ownerBalAfter == ownerBalBefore - amount
        );
    }
}

