contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address from, address to, uint256 amount, uint256 approveAmount) public payable {
        require(from != address(0) && to != address(0));
        require(amount > 0);
        require(approveAmount >= amount);

        // Give the sender tokens so that the transferFrom can succeed.
        // We use the payable getTokens path, but it distributes a fixed value from the contract itself.
        // Instead, we rely on the fact that the test contract is the owner and can transfer tokens.
        // However, the test contract may not have enough tokens. We need a way to give `from` tokens.
        // The contract P has a public `transfer` that moves tokens from the caller.
        // But the test contract is the owner and initially has totalDistributed tokens.
        // We can transfer from the test contract to `from`.
        require(c.balanceOf(address(this)) >= amount);
        c.transfer(from, amount);

        // Now `from` has at least `amount` tokens. Approve the spender (the test contract) to spend `approveAmount` tokens.
        // We need to call approve from `from`. But the test contract cannot call approve on behalf of `from`.
        // We can use transferFrom? No. We need to be the spender. The test contract is the spender.
        // But approve must be called by `from`. We cannot impersonate `from`.
        // So this rule is not testable with a single test contract unless we can make `from` be the test contract.
        // Let's change the rule: the test contract approves itself? No, transferFrom from the test contract to `to`.
        // Actually, we can test transferFrom where the spender is the test contract and the from is also the test contract.
        // So let's simplify: rule about transferFrom where spender == from == address(this).
        // But then it's just a transfer. Let's instead test the case where the spender is approved.
        // The test contract can call approve on itself? No, approve is called by msg.sender to approve spender.
        // The test contract can call c.approve(address(this), approveAmount) to approve itself.
        // Then c.transferFrom(address(this), to, amount) moves tokens from the test contract to `to`.
        // That tests the allowance deduction logic.

        // So let's redo the setup:
        // The test contract already has some tokens? It may not. We need to ensure it has enough.
        // The test contract is the owner and initially has totalDistributed tokens (from constructor).
        // But the constructor sets balances[owner] = totalDistributed, where owner = msg.sender at deployment.
        // The test contract deploys C, so msg.sender is the test contract, so the test contract is the owner and has totalDistributed tokens.
        // So c.balanceOf(address(this)) should be totalDistributed.
        // We can then approve ourselves and transferFrom.

        // But the rule we want is about transferFrom decreasing allowance and balance.
        // We'll do:
        // 1. Ensure the test contract has at least `amount` tokens.
        // 2. Approve the test contract itself for `approveAmount`.
        // 3. Record balances and allowance before.
        // 4. Call transferFrom(address(this), to, amount).
        // 5. Assert that balances[address(this)] decreased by amount, balances[to] increased by amount, and allowance[address(this)][address(this)] decreased by amount.

        // However, the test contract is the only actor. We can still test the allowance deduction.
        // But we need to ensure the approve call succeeds. The approve function has a check: if _value != 0 and allowed[msg.sender][_spender] != 0, return false.
        // Initially allowance is 0, so it should succeed.

        // Let's get the initial balance of the test contract.
        uint256 initialBalanceFrom = c.balanceOf(address(this));
        require(initialBalanceFrom >= amount);

        // Approve ourselves.
        c.approve(address(this), approveAmount);

        // Read allowance before.
        uint256 allowanceBefore = c.allowance(address(this), address(this));

        // Read balance of `to` before.
        uint256 balanceToBefore = c.balanceOf(to);

        // Perform transferFrom.
        c.transferFrom(address(this), to, amount);

        // Read after values.
        uint256 balanceFromAfter = c.balanceOf(address(this));
        uint256 balanceToAfter = c.balanceOf(to);
        uint256 allowanceAfter = c.allowance(address(this), address(this));

        assert(balanceFromAfter == initialBalanceFrom - amount &&
               balanceToAfter == balanceToBefore + amount &&
               allowanceAfter == allowanceBefore - amount);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address to, uint256 amount, uint256 approveAmount) public payable {
        require(to != address(0));
        require(amount > 0);
        require(approveAmount >= amount);

        // The test contract is the owner and has tokens from the constructor.
        // Ensure it has enough tokens for the transferFrom.
        require(c.balanceOf(address(this)) >= amount);

        // Approve the test contract itself as spender.
        bool approved = c.approve(address(this), approveAmount);
        require(approved);

        uint256 allowanceBefore = c.allowance(address(this), address(this));
        uint256 fromBalanceBefore = c.balanceOf(address(this));
        uint256 toBalanceBefore = c.balanceOf(to);

        // Perform the transferFrom.
        c.transferFrom(address(this), to, amount);

        uint256 allowanceAfter = c.allowance(address(this), address(this));
        uint256 fromBalanceAfter = c.balanceOf(address(this));
        uint256 toBalanceAfter = c.balanceOf(to);

        assert(fromBalanceBefore - fromBalanceAfter == amount &&
               toBalanceAfter - toBalanceBefore == amount &&
               allowanceBefore - allowanceAfter == amount);
    }

    receive() external payable {}
}

