        uint256 balanceBefore = c.balanceOf(address(this));
        uint256 totalRemainingBefore = c.totalRemaining();
        uint256 valueBefore = c.value();
        uint256 expectedAmount = valueBefore;
        if (expectedAmount > totalRemainingBefore) {
            expectedAmount = totalRemainingBefore;
        }

        bool reverted = false;
        try c.getTokens{value: ethAmount}() {
            // successful call
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = c.balanceOf(address(this));
        bool blacklistedAfter = c.blacklist(address(this));

        assert(
            reverted ||
            (expectedAmount > 0 &&
